als); out=[False]*m\n    for i,p in enumerate(pvals):\n        # p_i rejected iff for all j with p_j <= p_i: p_j <= alpha/(m-rank_j+1)\n        ok = all(q <= alpha/(m+1-r) for r,q in sorted([(sorted(pvals).index(q)+1, q) for q in pvals if q <= p], key=lambda t:t[1]))\n        out[i]=ok\n    return out\n\ntests = [\n    [0.41, 0.002, 0.03, 0.021, 0.0001] + [0.5]*18,\n    [0.001]*5 + [0.9]*18,                      # ties at small p\n    [0.05/23, 0.05/22*1.0001, 0.6]*1 + [0.7]*21, # boundary\n    [1.0]*23,\n]\nimport itertools, random\nrandom.seed(1)\ntests += [[random.random() for _ in range(23)] for _ in range(200)]\nfor k,t in enumerate(tests):\n    a, b = holm(t), holm_reference([x for x in t], 0.05)\n    assert a == b, (k, t, a, b)\nprint(\"HOLM CROSS-CHECK vs REFERENCE: PASS (\", len(tests), \"synthetic p-value vectors, incl. ties/boundaries)\")\nEOF\npython3 /workspace/design_validation/t03b_holm_reference.py", "timeout_seconds": 60, "kind": "ExecuteCheckAction"}, "tool_name": "execute_check", "tool_call_id": "chatcmpl-tool-94c7440f38eccac8", "tool_call": {"id": "chatcmpl-tool-94c7440f38eccac8", "responses_item_id": null, "name": "execute_check", "arguments": "{\"command\": \"cat > /workspace/design_validation/t03b_holm_reference.py <<'EOF'\\n# DESIGN VALIDATION ONLY - synthetic data, NOT experimental results.\\n# Cross-check holm() against a clean reference implementation with stepwise closure.\\ndef holm(pvals, alpha=0.05):\\n    order = sorted(range(len(pvals)), key=lambda i: pvals[i])\\n    prev_reject, out = True, [False]*len(pvals)\\n    for rank, i in enumerate(order):\\n        prev_reject = prev_reject and (pvals[i] <= alpha/(len(pvals)-rank))\\n        out[i] = prev_reject\\n    return out\\n\\ndef holm_reference(pvals, alpha=0.05):\\n    m = len(pvals); out=[False]*m\\n    for i,p in enumerate(pvals):\\n        # p_i rejected iff for all j with p_j <= p_i: p_j <= alpha/(m-rank_j+1)\\n        ok = all(q <= alpha/(m+1-r) for r,q in sorted([(sorted(pval